/* W15.5–15.6: one fictional FSP knowledge case. No chatbot, publication or real conversations. */
const KNOWLEDGE_ROUTES=['/staff/knowledge','/staff/chat-monitoring'];
const KNOWLEDGE={role:'lead',gapDraft:{kind:'missing',channel:'portal',language:'de',summary:'',checked:false},gap:null,draft:{de:'',en:'',source:'',date:'',rule:'',reason:''},versions:[],active:null,review:{note:'',checked:false},technical:false,check:{note:'',checked:false},checks:[],history:[],error:null};
function knowledgeAllowed(){return KNOWLEDGE_ROUTES.includes(route())&&['lead','admin','director'].includes(KNOWLEDGE.role)}
function knowledgeLead(){return knowledgeAllowed()&&KNOWLEDGE.role==='lead'}
function knowledgeLatest(){return KNOWLEDGE.versions.at(-1)}
function knowledgeClone(x){return JSON.parse(JSON.stringify(x))}
function knowledgeEvent(de,en,version=null){KNOWLEDGE.history.push({de,en,version,at:new Date().toISOString()})}
function knowledgeFail(de,en){KNOWLEDGE.error=[de,en];render();document.getElementById('knowledge-error')?.focus()}
function knowledgeInvalidate(){KNOWLEDGE.review.checked=false;const c=document.getElementById('knowledge-reviewed');if(c)c.checked=false}
function knowledgeDraftChanged(){knowledgeInvalidate();KNOWLEDGE.technical=false}
function knowledgeDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s+'T12:00:00Z');return !isNaN(d)&&d.toISOString().slice(0,10)===s&&s<=new Date().toISOString().slice(0,10)}
function knowledgeAction(action){if(!knowledgeAllowed())return;const k=KNOWLEDGE,v=knowledgeLatest();k.error=null;
 if(action==='gap'&&knowledgeLead()&&route()==='/staff/chat-monitoring'){
  const d=k.gapDraft;if(k.gap)return knowledgeFail('Das Muster führt genau eine Wissenslücke; vorhandenen Vorgang bearbeiten.','This sample handles one knowledge gap; continue the existing case.');
  if(!d.summary.trim()||!d.checked||!['missing','conflict'].includes(d.kind)||!['site','portal'].includes(d.channel)||!['de','en'].includes(d.language))return knowledgeFail('Abstrahierte fiktive Frage, Kanal, Sprache und Datenschutzprüfung ergänzen.','Provide an abstract fictional question, channel, language and privacy review.');
  k.gap={...knowledgeClone(d),id:'DEMO-KNOW-01',at:new Date().toISOString()};k.gapDraft.checked=false;knowledgeEvent('Wissenslücke zur Fachprüfung erfasst.','Knowledge gap recorded for subject review.');
 }else if(action==='submit'&&knowledgeLead()&&route()==='/staff/knowledge'){
  const d=k.draft;if(!k.gap||Object.values(d).some(x=>!x.trim())||!knowledgeDate(d.date))return knowledgeFail('Erfasste Lücke, DE/EN-Text, Quellenbezeichnung, gültiges Quelldatum, Regelversion und Änderungsgrund erforderlich.','Recorded gap, DE/EN text, source reference, valid source date, rule version and reason required.');
  if(v&&JSON.stringify(v.content)===JSON.stringify(d))return knowledgeFail('Unveränderte Fassung; keine neue Version angelegt.','Unchanged content; no new version created.');
  if(v?.status==='pending')return knowledgeFail('Offene Fassung zuerst prüfen oder zur Überarbeitung zurückgeben.','Review or return the pending version before submitting another.');
  k.versions.push({number:k.versions.length+1,content:knowledgeClone(d),gapId:k.gap.id,status:'pending',submitted:new Date().toISOString(),reviews:[]});k.review={note:'',checked:false};k.technical=false;knowledgeEvent('Unveränderliche Prüffassung angelegt.','Immutable review version created.',knowledgeLatest().number);
 }else if(action==='restore'&&knowledgeLead()&&route()==='/staff/knowledge'){
  if(!v)return;k.draft=knowledgeClone(v.content);k.review={note:'',checked:false};k.technical=false;
 }else if(['approve','return'].includes(action)&&knowledgeLead()&&route()==='/staff/knowledge'){
  if(!v||v.status!=='pending'||!k.review.note.trim()||!k.review.checked||JSON.stringify(v.content)!==JSON.stringify(k.draft))return knowledgeFail('Aktuelle unveränderte Prüffassung, Prüfnotiz und ausdrückliche DE/EN-/Quellenprüfung erforderlich.','Current unchanged review version, review note and explicit DE/EN/source review required.');
  v.status=action==='approve'?'approved':'returned';v.reviews.push({note:k.review.note.trim(),at:new Date().toISOString(),actor:'lead',outcome:v.status});k.review={note:'',checked:false};k.technical=false;knowledgeEvent(action==='approve'?'Fassung fachlich freigegeben; noch nicht übernommen.':'Fassung zur Überarbeitung zurückgegeben.',action==='approve'?'Version approved by subject lead; not yet adopted.':'Version returned for revision.',v.number);
 }else if(action==='activate'&&k.role==='admin'&&route()==='/staff/knowledge'){
  if(!v||v.status!=='approved'||!k.technical||k.active===v.number)return knowledgeFail('Neue fachlich freigegebene Fassung und technische Prüfung erforderlich.','A newly approved version and technical check are required.');
  k.active=v.number;k.technical=false;k.check={note:'',checked:false};knowledgeEvent('Fassung nur in lokale Muster-Wissensbasis übernommen.','Version adopted into the local sample knowledge base only.',v.number);
 }else if(action==='check'&&knowledgeLead()&&route()==='/staff/chat-monitoring'){
  if(!k.active||!k.check.note.trim()||!k.check.checked)return knowledgeFail('Aktive Musterfassung, manuelle Prüfnotiz und Bestätigung erforderlich.','Active sample version, manual review note and confirmation required.');
  k.checks.push({version:k.active,note:k.check.note.trim(),at:new Date().toISOString()});k.check={note:'',checked:false};knowledgeEvent('Manuelle Muster-Nachprüfung dokumentiert; keine Betriebskennzahl.','Manual sample follow-up recorded; no operational metric.',k.active);
 }else return;
 render();document.getElementById('knowledge-heading')?.focus();
}
function knowledgeButton(de,en,action){return `<button type="button" class="btn secondary" data-knowledge-action="${action}">${t(de,en)}</button>`}
function knowledgeField(key,de,en,value,group='draft',type='textarea'){return `<label class="field" for="knowledge-${group}-${key}">${t(de,en)}</label>${type==='textarea'?`<textarea class="knowledge-input" id="knowledge-${group}-${key}" data-knowledge-field="${key}" data-group="${group}" maxlength="2000">${esc(value)}</textarea>`:`<input class="knowledge-input" id="knowledge-${group}-${key}" data-knowledge-field="${key}" data-group="${group}" type="${type}" value="${esc(value)}" maxlength="500">`}`}
function knowledgeStatus(v){return v.status==='approved'?t('Fachlich freigegeben','Subject-approved'):v.status==='returned'?t('Überarbeitung erforderlich','Revision required'):t('Fachprüfung offen','Subject review pending')}
function knowledgeVersion(v){return `<article class="knowledge-version"><h3>${t('Fassung','Version')} ${v.number} · ${knowledgeStatus(v)}${KNOWLEDGE.active===v.number?' · '+t('lokal aktiv','locally active'):''}</h3><p>${esc(v.gapId)} · ${esc(v.submitted)}</p><div class="knowledge-language-grid"><div><h4>Deutsch</h4><p lang="de" class="learning-preserve">${esc(v.content.de)}</p></div><div><h4>English</h4><p lang="en" class="learning-preserve">${esc(v.content.en)}</p></div></div><p>${t('Quelle / Datum / Regelversion','Source / date / rule version')}: ${esc(v.content.source)} · ${esc(v.content.date)} · ${esc(v.content.rule)}</p><p>${t('Änderungsgrund','Reason for change')}: ${esc(v.content.reason)}</p>${v.reviews.map(r=>`<p class="learning-preserve">${t('Fachprüfung','Subject review')} · ${esc(r.at)} · ${esc(r.note)}</p>`).join('')}</article>`}
function knowledgeActive(){const v=KNOWLEDGE.versions.find(v=>v.number===KNOWLEDGE.active);return `<section class="learning-panel"><h2>${t('Lokale Antwortgrundlage','Local answer source')}</h2>${v?`<p>${t('Nur diese ausdrücklich übernommene Fassung erscheint in der lokalen Vorschau. Kein Anschluss an den echten Chatbot.','Only this explicitly adopted version appears in the local preview. No connection to the actual chatbot.')}</p>${knowledgeVersion(v)}`:`<p class="learning-empty">${t('Keine aktive Musterfassung. Keine belegte Antwort; persönliche Klärung erforderlich.','No active sample version. No supported answer; human clarification required.')}</p>`}</section>`}
function knowledgeMonitoring(){const k=KNOWLEDGE,d=k.gapDraft;return `<section class="learning-panel"><h2>${t('Wissenslücke zur Fachprüfung','Knowledge gap for subject review')}</h2><p>${t('Ein manuell eingegebener, abstrahierter FSP-Musterfall. Keine Gesprächskopie, Kundendaten, tatsächliche Chatstatistik oder automatische Vorschlagserzeugung.','One manually entered, abstract FSP sample case. No conversation copy, customer data, real chat metrics or automatic suggestion generation.')}</p>${k.gap?`<p>${esc(k.gap.id)} · FSP · ${k.gap.channel==='site'?t('Website','Website'):t('Portal','Portal')} · ${k.gap.language.toUpperCase()} · ${k.gap.kind==='missing'?t('Wissenslücke','Knowledge gap'):t('Regelwiderspruch','Rule conflict')}</p><p class="learning-preserve">${esc(k.gap.summary)}</p><p>${t('Zuständig: leitende DaF-Lehrkraft. Kein automatischer Abschluss durch Freigabe.','Responsible: lead DaF teacher. Approval does not automatically close this case.')}</p>`:knowledgeLead()?`<label class="field" for="knowledge-gap-kind">${t('Anlass','Reason')}</label><select id="knowledge-gap-kind" data-knowledge-field="kind" data-group="gapDraft"><option value="missing" ${d.kind==='missing'?'selected':''}>${t('Wissenslücke','Knowledge gap')}</option><option value="conflict" ${d.kind==='conflict'?'selected':''}>${t('Regelwiderspruch','Rule conflict')}</option></select><label class="field" for="knowledge-gap-channel">${t('Musterkanal','Sample channel')}</label><select id="knowledge-gap-channel" data-knowledge-field="channel" data-group="gapDraft"><option value="portal" ${d.channel==='portal'?'selected':''}>Portal</option><option value="site" ${d.channel==='site'?'selected':''}>Website</option></select><label class="field" for="knowledge-gap-language">${t('Sprache der Musterfrage','Sample question language')}</label><select id="knowledge-gap-language" data-knowledge-field="language" data-group="gapDraft"><option value="de" ${d.language==='de'?'selected':''}>Deutsch</option><option value="en" ${d.language==='en'?'selected':''}>English</option></select>${knowledgeField('summary','Abstrahierte Frage · nur fiktiv','Abstract question · fictional only',d.summary,'gapDraft')}<label class="attendance-check"><input type="checkbox" id="knowledge-gap-checked" ${d.checked?'checked':''}>${t('Nur eine allgemeine Musterfrage ohne personenbezogene Angaben übernommen','Only a general sample question without personal information included')}</label>${knowledgeButton('Lücke lokal erfassen','Record gap locally','gap')}`:`<p>${t('Noch keine Musterlücke erfasst.','No sample gap recorded yet.')}</p>`}</section>${knowledgeActive()}${knowledgeLead()?`<section class="learning-panel"><h2>${t('Wirkung manuell nachprüfen','Manually review the change')}</h2><p>${t('Prüfung bezieht sich ausdrücklich auf die aktive Musterfassung. Keine Erfolgsquote oder reale Gesprächsauswertung.','Review refers explicitly to the active sample version. No success rate or actual conversation analysis.')}</p>${knowledgeField('note','Manuelle Muster-Prüfnotiz','Manual sample review note',k.check.note,'check')}<label class="attendance-check"><input type="checkbox" id="knowledge-followup-checked" ${k.check.checked?'checked':''}>${t('Aktive Musterfassung geprüft','Active sample version reviewed')}</label>${knowledgeButton('Nachprüfung lokal dokumentieren','Record follow-up locally','check')}</section>`:''}<section class="learning-panel"><h2>${t('Nachprüfungen','Follow-up reviews')}</h2>${k.checks.length?k.checks.map(c=>`<article><p>${t('Fassung','Version')} ${c.version} · ${esc(c.at)}</p><p class="learning-preserve">${esc(c.note)}</p></article>`).join(''):`<p>${t('Noch keine Nachprüfung dokumentiert.','No follow-up review recorded yet.')}</p>`}</section>`}
function knowledgeEditor(){const k=KNOWLEDGE,v=knowledgeLatest();return `${knowledgeLead()?`<section class="learning-panel"><h2>${t('FSP-Wissensentwurf','FSP knowledge draft')}</h2><p>${t('Die leitende DaF-Musterrolle trägt die fachliche Verantwortung. Quellenangabe ist hier eine manuell geprüfte Referenz, kein automatischer Quellenabruf.','The sample lead DaF role has subject responsibility. The source reference is manually reviewed here; it is not fetched automatically.')}</p>${[['de','Antwortentwurf Deutsch','German answer draft'],['en','Antwortentwurf Englisch','English answer draft'],['source','Maßgebliche Quelle · Bezeichnung','Authoritative source · reference'],['date','Quelldatum','Source date'],['rule','Regelversion','Rule version'],['reason','Änderungsgrund','Reason for change']].map(([key,de,en])=>knowledgeField(key,de,en,k.draft[key],'draft',key==='date'?'date':'textarea')).join('')}${knowledgeButton('Prüffassung lokal anlegen','Create local review version','submit')}${v?knowledgeButton('Letzte Prüffassung in Entwurf laden','Load latest review version into draft','restore'):''}</section>`:''}<section class="learning-panel"><h2>${t('Aktuelle Prüffassung','Current review version')}</h2>${v?knowledgeVersion(v):`<p>${t('Noch keine Prüffassung. Entwürfe werden nicht als Antworten verwendet.','No review version yet. Drafts are not used as answers.')}</p>`}${knowledgeLead()&&v?.status==='pending'?`${knowledgeField('note','Fachliche Prüfnotiz','Subject review note',k.review.note,'review')}<label class="attendance-check"><input type="checkbox" id="knowledge-reviewed" ${k.review.checked?'checked':''}>${t('Genau diese DE/EN-Fassung und maßgebliche Quelle geprüft','This exact DE/EN version and authoritative source reviewed')}</label><div class="actions">${knowledgeButton('Fachlich freigeben · lokal','Approve content · locally','approve')}${knowledgeButton('Überarbeitung verlangen','Request revision','return')}</div>`:''}${k.role==='admin'&&v?.status==='approved'?`<label class="attendance-check"><input type="checkbox" id="knowledge-technical" ${k.technical?'checked':''}>${t('Genau diese fachlich freigegebene Fassung technisch geprüft','This exact subject-approved version technically checked')}</label>${knowledgeButton('Nur lokal übernehmen','Adopt locally only','activate')}`:''}</section>${knowledgeActive()}<details><summary>${t('Alle erhaltenen Fassungen','All retained versions')}</summary>${k.versions.map(knowledgeVersion).join('')}</details>`}
function knowledgePage(){const k=KNOWLEDGE,monitor=route()==='/staff/chat-monitoring';return `<section class="v2-content learning-journey knowledge-journey"><span class="eyebrow">${t('WISSEN · LOKALES MUSTER','KNOWLEDGE · LOCAL SAMPLE')}</span><h1 id="knowledge-heading" tabindex="-1">${monitor?t('Lücken erkennen. Änderungen prüfen.','Find gaps. Review changes.'):t('Geprüftes Wissen, nachvollziehbare Fassungen.','Reviewed knowledge, traceable versions.')}</h1><p class="learning-notice">${t('Nur fiktive Angaben im Arbeitsspeicher. Kein Live-Chatbot, keine Veröffentlichung, kein Versand. Neuladen verwirft das Muster. Rollenwahl ist keine Anmeldung.','Fictional information in memory only. No live chatbot, publication or sending. Reloading discards the sample. Role selection is not sign-in.')}</p><nav class="portal-nav"><a href="#/staff/knowledge">${t('Wissenspflege','Knowledge editing')}</a><a href="#/staff/chat-monitoring">${t('Monitoring · Musterfall','Monitoring · sample case')}</a></nav><label class="field" for="knowledge-role">${t('Musterrolle','Sample role')}</label><select id="knowledge-role">${[['lead','Leitende DaF-Lehrkraft','Lead DaF teacher'],['admin','Technische Administration','Technical administration'],['director','Geschäftsführung · Einsicht','Management · read only'],['other','Nicht zugeordnet','Unassigned']].map(([val,de,en])=>`<option value="${val}" ${k.role===val?'selected':''}>${t(de,en)}</option>`).join('')}</select>${k.error?`<p id="knowledge-error" role="alert" tabindex="-1">${t(...k.error)}</p>`:''}${knowledgeAllowed()?`${monitor?knowledgeMonitoring():knowledgeEditor()}<details><summary>${t('Lokaler Änderungsverlauf','Local change history')}</summary><ol>${k.history.map(h=>`<li>${esc(h.at)} · ${t(h.de,h.en)}${h.version?' · '+t('Fassung','Version')+' '+h.version:''}</li>`).join('')}</ol></details>`:`<p class="learning-empty">${t('Kein Zugriff auf diesen Musterfall.','No access to this sample case.')}</p>`}<p class="learning-source">WF-W15-05-02 / WF-W15-06-01 · W15.5–15.6. ${t('Teilweise lokale Vorbereitung. Produktive Quellen-/Publikations-/Rücknahmeverfahren, Kanalbindung, Kennzahlnenner, Berechtigungen und Aufbewahrung bleiben offen.','Partial local preparation. Production source/publication/withdrawal procedures, channel connections, metric denominators, permissions and retention remain open.')}</p></section>`}
const knowledgeBodyBefore=v3Body;v3Body=function(a){return KNOWLEDGE_ROUTES.includes(route())?knowledgePage():knowledgeBodyBefore(a)};
const knowledgeAssistantBefore=v3Assistant;v3Assistant=function(a){return KNOWLEDGE_ROUTES.includes(route())?`<aside class="assistant" id="context-companion" aria-label="${t('Wissensprüfung','Knowledge review')}"><div class="assistant-body"><h2>${t('Freigabe bleibt ein bewusster Schritt.','Approval remains an explicit step.')}</h2><p>${t('Ein Vorschlag ist keine freigegebene Regel. Fachprüfung und technische Übernahme sind getrennt.','A proposal is not an approved rule. Subject review and technical adoption are separate.')}</p><a class="suggestion" href="#/staff/knowledge">${t('Wissenspflege','Knowledge editing')}${arrow}</a><a class="suggestion" href="#/staff/chat-monitoring">${t('Muster-Monitoring','Sample monitoring')}${arrow}</a></div></aside>`:knowledgeAssistantBefore(a)};
const knowledgeBindBefore=v3Bind;v3Bind=function(){knowledgeBindBefore();if(!KNOWLEDGE_ROUTES.includes(route()))return;document.querySelectorAll('[data-knowledge-action]').forEach(e=>e.addEventListener('click',()=>knowledgeAction(e.dataset.knowledgeAction)));document.getElementById('knowledge-role')?.addEventListener('change',e=>{if(!['lead','admin','director','other'].includes(e.target.value))return;KNOWLEDGE.role=e.target.value;KNOWLEDGE.error=null;KNOWLEDGE.review.checked=false;KNOWLEDGE.technical=false;KNOWLEDGE.check.checked=false;KNOWLEDGE.gapDraft.checked=false;render();document.getElementById('knowledge-heading')?.focus()});document.querySelectorAll('[data-knowledge-field]').forEach(e=>e.addEventListener(e.tagName==='SELECT'?'change':'input',()=>{if(!knowledgeLead())return;const g=e.dataset.group,key=e.dataset.knowledgeField;if(!['draft','review','check','gapDraft'].includes(g)||!Object.hasOwn(KNOWLEDGE[g],key))return;KNOWLEDGE[g][key]=e.value;if(g==='draft')knowledgeDraftChanged();if(g==='review')knowledgeInvalidate();if(g==='check'||g==='gapDraft'){KNOWLEDGE[g].checked=false;const c=document.getElementById(g==='check'?'knowledge-followup-checked':'knowledge-gap-checked');if(c)c.checked=false}}));for(const [id,g,key,role] of [['knowledge-reviewed','review','checked','lead'],['knowledge-followup-checked','check','checked','lead'],['knowledge-gap-checked','gapDraft','checked','lead'],['knowledge-technical',null,'technical','admin']])document.getElementById(id)?.addEventListener('change',e=>{if(!knowledgeAllowed()||KNOWLEDGE.role!==role)return;if(g)KNOWLEDGE[g][key]=e.target.checked;else KNOWLEDGE[key]=e.target.checked})};
render();
